/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    EXU_Topic topic = 'FinalTestSMS2';    // <-- Specify the Communication Topic name here

    // EXU_CommunicationTopics
    EXU_CommunicationTopics commTopics, newCommTopics;

    select firstonly commTopics;
    select firstonly newCommTopics
      where newCommTopics.Topic == topic;

    if (commTopics.RecId && !newCommTopics.RecId)
    {
        buf2Buf(commTopics, newCommTopics);
        newCommTopics.Topic              = topic;
        newCommTopics.CommunicationTopic = EXU_CommunicationTopic::RegardingNotification; // <-- Specify the CommunicationTopic enum value here
        newCommTopics.insert();
        info(strFmt("Inserted EXU_CommunicationTopics: %1", topic));
    }

    // EXU_CommunicationTopicMethod
    EXU_CommunicationTopicMethod commTopicMethod, newCommTopicMethod;

    select firstonly commTopicMethod;
    select firstonly newCommTopicMethod
      where newCommTopicMethod.Topic              == topic
         && newCommTopicMethod.CommunicationMethod == EXU_CommunicationMethod::SMS; // <-- Specify the CommunicationMethod enum value here

    if (commTopicMethod.RecId && !newCommTopicMethod.RecId)
    {
        buf2Buf(commTopicMethod, newCommTopicMethod);
        newCommTopicMethod.Topic               = topic;
        newCommTopicMethod.CommunicationMethod = EXU_CommunicationMethod::SMS; // <-- Specify the CommunicationMethod enum value here (match above)
        newCommTopicMethod.EGS_ShowOnWeb       = NoYes::Yes;
        newCommTopicMethod.insert();
        info(strFmt("Inserted EXU_CommunicationTopicMethod: %1 / %2", topic, EXU_CommunicationMethod::SMS));
    }
}
